  ('40e43546-1a34-4982-879a-9bf519f8c9e3', '2026-09-14 11:41:22.710037+00', '74179eb0-cdad-4329-9ece-cb7f5c3da007', 'onyebuchi.ism@gmail.com', 'super-admin', 'INSERT', 'announcements', '6e187ecf-7e46-467f-b413-7132429c216d', 'jbuibj', NULL, NULL, '{"id": "6e187ecf-7e46-467f-b413-7132429c216d", "body": "jkbjbio", "title": "jbuibj", "archived": false, "category": "jkbj", "image_url": null, "is_active": true, "created_at": "2026-09-14T11:41:22.710037+00:00", "created_by": null, "updated_at": "2026-09-14T11:41:22.710037+00:00", "published_at": "2026-09-14T11:41:22.710037+00:00"}'),
  ('977d8aec-8962-4865-a660-0f57d3126855', '2026-09-14 11:41:28.168317+00', '74179eb0-cdad-4329-9ece-cb7f5c3da007', 'onyebuchi.ism@gmail.com', 'super-admin', 'DELETE', 'announcements', '6e187ecf-7e46-467f-b413-7132429c216d', 'jbuibj', NULL, '{"id": "6e187ecf-7e46-467f-b413-7132429c216d", "body": "jkbjbio", "title": "jbuibj", "archived": false, "category": "jkbj", "image_url": null, "is_active": true, "created_at": "2026-09-14T11:41:22.710037+00:00", "created_by": null, "updated_at": "2026-09-14T11:41:22.710037+00:00", "published_at": "2026-09-14T11:41:22.710037+00:00"}', NULL),
  ('d6ecf996-79b7-4f76-bd84-f238e3135243', '2026-09-14 16:19:51.026677+00', '3d40f6e5-08ad-4cf3-a92b-0a31058da012', 'ebunregina.ism@gmail.com', 'super-admin', 'INSERT', 'announcements', '1e279fc1-522c-4bef-8500-8ad1cf1be8ba', 'ANNOUNCEMENT FOR THE WEEK, STARTING MONDAY 14th, SEPTEMBER 2026.', NULL, NULL, '{"id": "1e279fc1-522c-4bef-8500-8ad1cf1be8ba", "body": "‎IT''S OUR MONTH OF GROWTH AND STILL IN THE SEASON OF MANIFESTATIONS. GLORY BE To GOD!\n‎\n‎COUNTING ON ALL OUR ESTEEMED CELL LEADERS AND MINISTERS TO ORGANIZE ISM MINISTERS AND LEADERS CONFERENCE THROUGHOUT THE MONTH OF AUGUST AND SEPTEMBER 2026\n‎\n‎Be a part of it as we strategize with our man of God to reach the last lost soul, by confirming your dates!!!\n‎\n‎Register your conference @:\n‎https://ministersconference.christembassy-ism.org\n‎\n‎We are available for effective planning and execution with you and your team. Contact your liaison manager\n‎\n‎Minister’s praise and prayer conference\n‎Tuesday 15th September, 2026\n‎\n‎Praise Night with Pastor Chris\n‎Sun 20th September, 2026\n‎\n‎🙏 Global Day of Prayer (27th Edition) & Global Prayer and Fasting\n‎📅 Friday, 25th – Sunday, 27th September 2026\n‎\n‎🍂 OCTOBER 2026\n‎💫 Healing Streams Live Healing Services\n‎📅 Friday, 23rd – Sunday, 25th October 2026\n‎🏢 Onsite\n‎\n‎🙏 Global Prayer and Fasting\n‎📅 Tuesday, 27th – Thursday, 29th October 2026\n‎\n‎🍁 NOVEMBER 2026\n‎🌍 International Pastors’ and Partners’ Conference ( IPPC) Monday, 9th – Sunday, 15th November 2026🏢 Onsite\n‎\n‎\n‎Global Prayer and Fasting.\n‎Friday 25th- Sunday 27th September, 2026\n‎\n‎Other Important announcements for today are as follows:\n‎1. REGISTER TODAY FOR THE ISM ONLINE SCHOOL:\n‎➡ @ school.christembassy-ism.com\n‎SO MUCH TO EXPECT AND GAIN AT THE ISM ONLINE SCHOOL\n‎\n‎ENROL NOW- school.christembassy-ism.com\n‎\n‎2. NOW AVAILABLE: THE REBROADCAST OF INSPIRING MONTH OF SEPTEMBER CELL LEADERS TRAINING WITH THE HIGHLY ESTEEMED EXECUTIVE MINISTER\n‎\n‎Participation Links:\n‎For ISM Cell Leaders:\n‎https://app.christembassy-ism.org/cell\n‎\n‎For ISM Cell Members and Stakeholders:\n‎https://school.christembassy-ism.com/training\n‎\n‎3. POST - GMC ACTIVITIES:\n‎\n‎3A. HAPPENING THROUGHOUT THIS SEASON: ISM MINISTERS AND LEADERS CONFERENCE in your city, country and region\n‎\n‎kindly choose a date and Start planning for the meeting with your liaison manager\n‎We are available for effective planning and execution with every team.\n‎\n‎Register your conference @:\n‎https://ministersconference.christembassy-ism.org\n‎\n‎\n‎C. GET THESE NEWLY DEVELOPED SOLUTION KITS FOR ISM MINISTERS BY OUR DEAR MAN OF GOD, PASTOR CHRIS:\n‎\n‎1. MYSTERIES ABOUT MONEY: https://ce-ism.org/yLKj4C\n‎\n‎2) SUCCESS PLAYBOOK: https://ce-ism.org/tukgBC\n‎\n‎Kindly click and register first to get your login details before purchasing any of the packages.\n‎\n‎4. Visit the ISM Prayer Network website today:\n‎To get latest updates on ISM Prayer Network, Create your Prayer Group, host your meetings and Submit your Prayer meeting reports.\n‎@ www.ismprayernetwork.org/prayergroup\n‎\n‎We look forward to receiving testimonies of maximum attendance and great exploits from your Prayer meeting @ ismprayernetwork.org\n‎\n‎1. WE PRAY EVERY DAY! TO SUBMIT YOUR PRAYER MEETING REPORT, KINDLY FOLLOW THE STEP-BY-STEP GUIDE ACCORDINGLY.\"\n‎\n‎1. \"Kindly download and activate the KingsChat app to enable swift submission of your Prayer Meeting Reports @ \"ISM PRAYER ROOMS CONTENT HUB\". Join -using this KingsChat URL: https://www.kingsch.at/jl/bld0YW\n‎\n‎2. Kindly share your prayer meeting link to ensure a detailed record of your prayer group within your region is maintained.\n‎\n‎\n‎5. Book of the Month: How to make your faith work!\nVisit our website today to subscribe for your e-copy or order for your hard copy@ ismprayernetwork.org/bookstore\n\n‎\n\n‎If you are here and require us to pray with you or counsel with you, kindly wait after the benediction so that we can give you adequate attention.\n‎\n‎GRATITUDE: We thank you for your invaluable partnership with the ISM. God is doing great and mighty things through the International School of Ministry and through our dear Man of God all around the world.\n‎\n‎Furthermore, your offerings, tithes, and special seeds should kindly be paid into any of the ISM accounts, also, offerings for other ISM & Love world projects are being received. God will honor your seed sown and grant you the desires of your hearts. He will replenish you and your ministries in a thousand-fold, Amen.\n‎\n‎_ISM ... Impacting Ministers for Effective Ministry\n‎", "title": "ANNOUNCEMENT FOR THE WEEK, STARTING MONDAY 14th, SEPTEMBER 2026.", "archived": false, "category": "general", "image_url": null, "is_active": true, "created_at": "2026-09-14T16:19:51.026677+00:00", "created_by": null, "updated_at": "2026-09-14T16:19:51.026677+00:00", "published_at": "2026-09-14T16:19:51.026677+00:00"}'),
