  ('b84eccb0-ebdc-4e67-8fc7-a3c38bad0e9d', '2026-10-07 12:53:36.214903+00', NULL, NULL, NULL, 'INSERT', 'contacts', '84fd294a-c9aa-4b8b-a977-66bbfc952b0d', 'revivalprayerministriesjoy@gmail.com', NULL, NULL, '{"id": "84fd294a-c9aa-4b8b-a977-66bbfc952b0d", "city": null, "email": "revivalprayerministriesjoy@gmail.com", "notes": null, "phone": null, "title": null, "source": "platform_signup", "country": "India", "dob_day": null, "dob_month": null, "last_name": "Pushparaj", "created_at": "2026-10-07T12:53:36.214903+00:00", "first_name": "Mathew", "group_name": null, "updated_at": "2026-10-07T12:53:36.214903+00:00", "ministerial_role": null}'),
  ('84abd82c-6f1e-459d-8a7f-3280925a0fbd', '2026-10-07 12:53:36.922078+00', NULL, NULL, NULL, 'INSERT', 'contact_messages', 'bbc452f2-c9c7-4509-a459-2e04987a46d3', 'Evangelist Mathew Pushparaj', NULL, NULL, '{"id": "bbc452f2-c9c7-4509-a459-2e04987a46d3", "name": "Evangelist Mathew Pushparaj", "email": "revivalprayerministriesjoy@gmail.com", "message": "New minister registration note: Greetings in the precious name of Jesus Christ.\n\nMy name is Evg. Mathew, and I serve with Revival Prayer Ministries in Coimbatore, India.\n\nWe are involved in prayer ministry, evangelism, village outreach, deliverance, healing, discipleship and equipping believers. We have a desire to connect with pastors and ministry leaders from different nations for prayer, fellowship, encouragement and Kingdom collaboration.\n\nI came across the Ministers prayer network and was very encouraged by your vision of bringing pastoral leaders together in authentic spiritual and relational unity.\n\nI would be grateful to know how I can connect with a ministers prayer net, especially an international or India-based group. We would also be happy to build relationships with pastors and ministry leaders who share this heart for prayer and Kingdom unity.\n\nThank you for your ministry. Please keep Revival Prayer Ministries in your prayers.\n\nBlessings in Christ,\nEvg. Mathew\nRevival Prayer Ministries\nCoimbatore, India", "created_at": "2026-10-07T12:53:36.922078+00:00"}'),
