  ('6397a517-4632-4902-8656-43eb68c2c4dc', '2026-10-14 04:53:23.583434+00', NULL, NULL, NULL, 'INSERT', 'contacts', '0b1a2862-c1bb-4fa7-9473-caac6e1e3744', 'raphaelyeigba@gmail.com', NULL, NULL, '{"id": "0b1a2862-c1bb-4fa7-9473-caac6e1e3744", "city": null, "email": "raphaelyeigba@gmail.com", "notes": null, "phone": null, "title": null, "source": "platform_signup", "country": null, "dob_day": null, "dob_month": null, "last_name": "Woyengikuro Yeigba", "created_at": "2026-10-14T04:53:23.583434+00:00", "first_name": "Raphael", "group_name": null, "updated_at": "2026-10-14T04:53:23.583434+00:00", "ministerial_role": null}'),
